#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;
    long long k;
    cin >> k;
    vector<string> w(k);
    for (int i = 0; i < k; i++) cin >> w[i];

    int n = s.size(), L = w[0].size();
    unordered_map<string, int> need;
    for (int i = 0; i < k; i++) need[w[i]]++;
    vector<int> result;
    for (int off = 0; off < L; off++) {
        unordered_map<string, int> have;
        int left = off, count = 0;
        for (int right = off; right + L <= n; right += L) {
            string word = s.substr(right, L);
            if (need.count(word)) {
                have[word]++;
                count++;
                while (have[word] > need[word]) {
                    have[s.substr(left, L)]--;
                    left += L;
                    count--;
                }
                if (count == k) {
                    result.push_back(left);
                    have[s.substr(left, L)]--;
                    left += L;
                    count--;
                }
            } else {
                have.clear();
                count = 0;
                left = right + L;
            }
        }
    }
    sort(result.begin(), result.end());
    cout << result.size() << "\n";
    for (size_t i = 0; i < result.size(); i++) cout << result[i] << (i + 1 < result.size() ? " " : "");
    cout << "\n";

    return 0;
}

